package com.autoops.auth.security;import com.autoops.auth.service.JwtService;import com.autoops.user.repository.UserRepository;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;@Component public class JwtAuthenticationFilter extends OncePerRequestFilter{private final JwtService jwt;private final UserRepository users;public JwtAuthenticationFilter(JwtService j,UserRepository u){jwt=j;users=u;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{var c=jwt.parse(h.substring(7));Long id=Long.valueOf(c.getSubject());var u=users.findById(id).orElseThrow();if(u.getStatus()==com.autoops.user.entity.User.Status.ACTIVE){var a=new UsernamePasswordAuthenticationToken(u.getUsername(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name())));SecurityContextHolder.getContext().setAuthentication(a);}}catch(Exception ignored){SecurityContextHolder.clearContext();}}chain.doFilter(req,res);}}
